#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSideLength(std::vector<std::vector<int>>& mat, int threshold) {
        int m = mat.size(), n = mat[0].size();
        std::vector<std::vector<int>> pref(m + 1, std::vector<int>(n + 1, 0));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                pref[r + 1][c + 1] = mat[r][c] + pref[r][c + 1] + pref[r + 1][c] - pref[r][c];
            }
        }
        auto query = [&](int r1, int c1, int r2, int c2) {
            return pref[r2][c2] - pref[r1][c2] - pref[r2][c1] + pref[r1][c1];
        };
        int lo = 0, hi = std::min(m, n), ans = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (mid == 0) { lo = mid + 1; continue; }
            bool found = false;
            for (int r = 0; r <= m - mid; ++r) {
                for (int c = 0; c <= n - mid; ++c) {
                    if (query(r, c, r + mid, c + mid) <= threshold) {
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
            if (found) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxSideLength(int[][] mat, int threshold) {
        int m = mat.length, n = mat[0].length;
        int[][] pref = new int[m + 1][n + 1];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                pref[r + 1][c + 1] = mat[r][c] + pref[r][c + 1] + pref[r + 1][c] - pref[r][c];
            }
        }
        int lo = 0, hi = Math.min(m, n), ans = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (mid == 0) { lo = mid + 1; continue; }
            boolean found = false;
            for (int r = 0; r <= m - mid; r++) {
                for (int c = 0; c <= n - mid; c++) {
                    int sum = pref[r + mid][c + mid] - pref[r][c + mid] - pref[r + mid][c] + pref[r][c];
                    if (sum <= threshold) {
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
            if (found) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
}

